package io.github.testlens.compatibility.tooling;

import io.github.testlens.compatibility.engine.CompatibilityComparisonReport;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.util.Objects;

/** Standalone, no-network HTML rendering of the canonical comparison model. */
public final class CompatibilityReportHtml {
    public static final long MAX_OUTPUT_BYTES=64L*1024*1024;
    public byte[] write(CompatibilityComparisonReport r){Objects.requireNonNull(r);StringBuilder s=new StringBuilder(16384);s.append("<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Test Lens compatibility report</title><style>body{font:14px system-ui;margin:2rem;color:#18202b}table{border-collapse:collapse;width:100%}th,td{border:1px solid #ccd3dc;padding:.45rem;text-align:left;vertical-align:top}select{margin:0 .7rem .8rem 0}.warn{font-weight:700}code{overflow-wrap:anywhere}</style><body>");s.append("<h1>Compatibility comparison</h1><p><b>Axis:</b> ").append(e(r.intent().axis().name())).append(" · ").append(e(r.intent().baselineRole())).append(" vs ").append(e(r.intent().variantRole())).append("</p><p class=\"warn\">Coverage applies only to supplied matched invocations; this is not a whole-application guarantee.</p>");s.append("<h2>Coverage</h2><p>Matched: ").append(r.coverage().matched()).append("; regressions: ").append(r.coverage().regressions()).append("; behavioral deltas: ").append(r.coverage().behavioralDeltas()).append("; ambiguous: ").append(r.coverage().ambiguous()).append(".</p>");s.append("<label>Outcome <select id=\"outcome\"><option value=\"\">all</option></select></label><label>Comparability <select id=\"comparability\"><option value=\"\">all</option></select></label><label>Severity <select id=\"severity\"><option value=\"\">all</option></select></label><label>Category <select id=\"category\"><option value=\"\">all</option></select></label><label>Causal state <select id=\"causal\"><option value=\"\">all</option></select></label>");s.append("<h2>Test comparisons</h2><table><thead><tr><th>Test</th><th>Results</th><th>Outcome</th><th>Comparability</th><th>Behavior/evidence</th><th>Recommendations</th><th>Code change</th></tr></thead><tbody>");for(var x:r.testComparisons()){s.append("<tr data-outcome=\"").append(e(x.outcome().name())).append("\" data-comparability=\"").append(e(x.comparability().status().name())).append("\"><td><code>").append(e(x.testIdentityRef())).append("</code></td><td>").append(e(x.baseline().terminalStatus().name())).append(" → ").append(e(x.variant().terminalStatus().name())).append("<br>attempts ").append(x.baseline().attemptCount()).append(" → ").append(x.variant().attemptCount()).append("</td><td>").append(e(x.outcome().name())).append("</td><td>").append(e(x.comparability().status().name())).append("<br>").append(e(String.join(", ",x.comparability().reasonCodes()))).append("</td><td>");for(var g:x.behaviorDiff().groups())s.append(e(g.group())).append(": ").append(e(g.state().name())).append("<br>");s.append("</td><td>").append(e(x.recommendationCodes().toString())).append("<br>").append(e(x.verificationScope().toString())).append("</td><td>").append(e(x.codeChangeRequired().name())).append("</td></tr>");}s.append("</tbody></table><h2>Findings</h2><table><thead><tr><th>Code</th><th>Category</th><th>Severity</th><th>Causal state/confidence</th><th>Evidence</th></tr></thead><tbody>");for(var f:r.findings())s.append("<tr data-severity=\"").append(e(f.severity().name())).append("\" data-category=\"").append(e(f.category().name())).append("\" data-causal=\"").append(e(f.causalState().name())).append("\"><td>").append(e(f.code())).append("</td><td>").append(e(f.category().name())).append("</td><td>").append(e(f.severity().name())).append("</td><td>").append(e(f.causalState().name())).append(" / ").append(e(f.confidence().name())).append("</td><td>").append(e(f.evidence().toString())).append("</td></tr>");s.append("</tbody></table><h2>Limitations</h2><p>").append(e(r.outputLimitations().toString())).append("</p><script>(()=>{const ids=['outcome','comparability','severity','category','causal'];for(const id of ids){const key=id;const rows=[...document.querySelectorAll('tr[data-'+key+']')];const sel=document.getElementById(id);for(const v of [...new Set(rows.map(r=>r.dataset[key]))].sort()){const o=document.createElement('option');o.value=v;o.textContent=v;sel.append(o)}sel.addEventListener('change',()=>{for(const row of rows)row.hidden=!!sel.value&&row.dataset[key]!==sel.value})}})()</script></body></html>\n");byte[]out=s.toString().getBytes(StandardCharsets.UTF_8);if(out.length>MAX_OUTPUT_BYTES)throw new CompatibilityReportJson.ReportFormatException("OUTPUT_LIMIT_EXCEEDED");return out;}
    public Path writeDefault(CompatibilityComparisonReport report,Path projectRoot)throws IOException{Path destination=CompatibilityReportJson.safeDestination(projectRoot,Path.of("target","test-lens","compatibility","reports","compatibility-v1.html"),"compatibility-v1.html");CompatibilityReportJson.atomic(destination,write(report));return destination;}
    static String e(String value){if(value==null)return"";return value.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");}
}
